    ldrb r2,[r1,#0x15]                       @ 080f42a8 4a7d
    ands r0,r2    @ 080f42aa 1040
    strb r0,[r1,#0x15]                       @ 080f42ac 4875
    bx lr                                    @ 080f42ae 7047
